with kept_keys as (select channel from orders intersect all select channel from orders where customer_id = 25), reconciled as (select s.* from orders s join kept_keys k on s.channel = k.channel) select s.id, s.customer_id, s.store_id, s.order_date, s.status, s.amount, s.shipping_fee, case when status rlike '^(COMPLETED|SHIPPED)$' then 'EXTENDED' when status rlike '^(PENDING|CANCELLED)$' then 'GROUP_A' else 'OTHER_ZONE' end as status_zone, (select sum(x.revenue) from store_sales x where x.store_id = s.store_id) as sum_store_sale_revenue from reconciled s order by order_date nulls first;
